"use client";

import { type MenuProps, Menu as MenuRoot } from "./menu";
import { MenuDivider, type MenuDividerProps } from "./menu-divider";
import { MenuGroup, type MenuGroupProps } from "./menu-group";
import { MenuItem, type MenuItemProps } from "./menu-item";
import { MenuItemCheckbox, type MenuItemCheckboxProps } from "./menu-item-checkbox";
import { MenuItemRadio, type MenuItemRadioProps } from "./menu-item-radio";
import { MenuLabel, type MenuLabelProps } from "./menu-label";
import {
  MenuSub,
  MenuSubContent,
  type MenuSubContentProps,
  type MenuSubMode,
  type MenuSubProps,
  MenuSubTrigger,
  type MenuSubTriggerProps,
} from "./menu-sub";

const Menu = Object.assign(MenuRoot, {
  Item: MenuItem,
  ItemCheckbox: MenuItemCheckbox,
  ItemRadio: MenuItemRadio,
  Divider: MenuDivider,
  Group: MenuGroup,
  Label: MenuLabel,
  Sub: MenuSub,
  SubTrigger: MenuSubTrigger,
  SubContent: MenuSubContent,
});

export { Menu, type MenuProps };
export { MenuItem, type MenuItemProps };
export { MenuItemCheckbox, type MenuItemCheckboxProps };
export { MenuItemRadio, type MenuItemRadioProps };
export { MenuDivider, type MenuDividerProps };
export { MenuGroup, type MenuGroupProps };
export { MenuLabel, type MenuLabelProps };
export { MenuSub, type MenuSubProps, type MenuSubMode };
export { MenuSubTrigger, type MenuSubTriggerProps };
export { MenuSubContent, type MenuSubContentProps };

"use client";

import {
  type ComponentPropsWithRef,
  type KeyboardEvent,
  type ReactNode,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
import { useComposedRefs } from "@/hooks/use-composed-refs";
import {
  collectListboxItems,
  getEncodedListboxItemId,
  type ListboxMetadataItem,
  useListbox,
} from "@/hooks/use-listbox";
import { useSelectableCollection } from "@/lib/selectable-collection";
import { cn } from "@/lib/utils";
import {
  type CustomActivator,
  MenuContext,
  type MenuContextValue,
  type MenuSubEntry,
} from "./menu-context";
import { MenuGroup } from "./menu-group";
import { MenuItem } from "./menu-item";
import { MenuItemCheckbox } from "./menu-item-checkbox";
import { MenuItemRadio } from "./menu-item-radio";
import { MenuStackBack } from "./menu-stack";

/**
 * @typeParam TId - Convenience assertion for the id union surfaced through
 * `selectedId`/`onSelect`/`onHighlightChange`. Ids originate from `Menu.Item`
 * children props and are asserted to `TId`, not validated.
 */
export interface MenuProps<TId extends string = string>
  extends Omit<ComponentPropsWithRef<"div">, "aria-label" | "children" | "onKeyDown" | "onSelect"> {
  /**
   * Controlled selected item id. Pair with onSelect. Switches item role to "menuitemradio" with
   * aria-checked.
   */
  selectedId?: TId | null;
  /**
   * Initial selected id for uncontrolled mode. Setting this to a non-null value enables
   * selection semantics.
   */
  defaultSelectedId?: TId | null;
  /** Controlled highlighted (focused) item id. Pair with onHighlightChange. */
  highlighted?: TId | null;
  /** Initial highlighted id for uncontrolled mode. */
  defaultHighlighted?: TId | null;
  /** Fired when an item is activated by click, Enter, or Space. */
  onSelect?: (id: TId) => void;
  /** Fired when the highlighted item changes via arrow keys, typeahead, or mouse. */
  onHighlightChange?: (value: TId | null) => void;
  /** Fired when Escape or Tab is pressed. */
  onClose?: () => void;
  /**
   * Visual layout. `detail` renders taller, divider-separated rows with a right-aligned value
   * column, for menus where each item carries a status or summary value.
   */
  variant?: "default" | "detail";
  /** When true, arrow navigation wraps from last item to first and vice versa. */
  wrap?: boolean;
  /**
   * Enable type-ahead character search to jump to matching items. Submenus
   * inherit this setting. Disable when every printable key the menu advertises
   * belongs to an external hotkey layer.
   * @default true
   */
  typeahead?: boolean;
  /** MenuItem and MenuDivider children. */
  children: ReactNode;
  /** Auto-focus the menu container on mount so arrow keys work without an explicit click. */
  autoFocus?: boolean;
  /** Accessible name for the menu container. */
  "aria-label"?: string;
  /** Called after the built-in menu key handling runs. */
  onKeyDown?: (event: KeyboardEvent) => void;
}

/**
 * Terminal-styled selection list with keyboard navigation, highlighting and optional hotkey
 * indicators.
 */
export function Menu<TId extends string = string>({
  selectedId: controlledSelectedId,
  defaultSelectedId = null,
  highlighted: controlledHighlighted,
  defaultHighlighted = null,
  onSelect,
  onHighlightChange,
  onClose,
  variant = "default",
  wrap = true,
  typeahead = true,
  className,
  "aria-label": ariaLabel,
  autoFocus,
  children,
  onKeyDown,
  ref,
  ...rootProps
}: MenuProps<TId>) {
  const idPrefix = useId();
  const menuRef = useRef<HTMLDivElement>(null);
  const composedRef = useComposedRefs(menuRef, ref);
  const customActivators = useRef<Map<string, CustomActivator>>(new Map());
  const [registrationsStarted, setRegistrationsStarted] = useState(false);
  const [activeSub, setActiveSub] = useState<MenuSubEntry | null>(null);
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [stackContainer, setStackContainer] = useState<HTMLDivElement | null>(null);
  const highlightRef = useRef<((id: TId) => void) | null>(null);
  const activeSubRef = useRef<MenuSubEntry | null>(null);
  const selectionEnabled = controlledSelectedId !== undefined || defaultSelectedId !== null;
  const itemRole = selectionEnabled ? "menuitemradio" : "menuitem";

  const { items: visibleItems, registerItem, unregisterItem } = useSelectableCollection(menuRef);
  const visibleMetadata = useMemo<ListboxMetadataItem<TId>[]>(
    () => visibleItems.map((item) => ({ id: item.value as TId, disabled: item.disabled })),
    [visibleItems],
  );
  const renderSeed = useMemo(
    () =>
      collectListboxItems<TId>(children, {
        itemTypes: [MenuItem, MenuItemCheckbox, MenuItemRadio],
        containerTypes: [MenuGroup],
      }),
    [children],
  );
  const items = registrationsStarted ? visibleMetadata : renderSeed;

  const handleRegisterItem = useCallback(
    (registrationId: string, value: string, disabled: boolean, element: HTMLElement | null) => {
      setRegistrationsStarted(true);
      registerItem(registrationId, value, disabled, element);
    },
    [registerItem],
  );

  const hover = useCallback((id: string) => setHoveredId(id), []);

  // Last pointer coordinates seen anywhere in this menu, owned by the root so a
  // row the pointer never visited still judges "moved" against the pointer's
  // real last position. Navigation keys clear the hover, and it must stay
  // cleared until the pointer actually travels — browsers (Safari especially)
  // re-fire pointermove with unchanged coordinates on re-renders and scrolls,
  // which would hand the hover straight back to a stationary cursor.
  const lastPointerRef = useRef<{ x: number; y: number } | null>(null);
  const trackPointer = useCallback((x: number, y: number) => {
    const last = lastPointerRef.current;
    const moved = last === null || last.x !== x || last.y !== y;
    lastPointerRef.current = { x, y };
    return moved;
  }, []);

  // Only the owner releases: pointerleave on the row the pointer came FROM fires
  // after pointermove already handed the hover to the next row, and must not
  // clear the new owner.
  const unhover = useCallback((id: string) => {
    setHoveredId((prev) => (prev === id ? null : prev));
  }, []);

  // The hovered row unmounts on a drill-down transition, so its pointerleave
  // never fires; drop the hover with the rows it belonged to.
  const pushSub = useCallback((entry: MenuSubEntry) => {
    setHoveredId(null);
    setActiveSub(entry);
  }, []);

  const popSub = useCallback((id?: string) => {
    const current = activeSubRef.current;
    if (current === null) return;
    // A submenu unmounting after a sibling already pushed must not pop the
    // sibling's entry, so a caller can name the entry it owns.
    if (id !== undefined && id !== current.id) return;
    setHoveredId(null);
    setActiveSub(null);
    highlightRef.current?.(current.id as TId);
  }, []);

  const registerActivator = useCallback((id: string, handler: CustomActivator) => {
    customActivators.current.set(id, handler);
  }, []);

  const unregisterActivator = useCallback((id: string) => {
    customActivators.current.delete(id);
  }, []);

  const { selectedId, highlighted, handleItemActivate, handleItemHighlight, getContainerProps } =
    useListbox<TId>({
      selectedId: selectionEnabled ? controlledSelectedId : null,
      defaultSelectedId: selectionEnabled ? defaultSelectedId : null,
      highlighted: controlledHighlighted,
      defaultHighlighted,
      onSelect,
      onHighlightChange,
      wrap,
      idPrefix,
      onKeyDown: (e: KeyboardEvent) => {
        // Keyboard takes over: the hover is cosmetic and must not linger under a
        // stationary cursor once navigation moves the real cursor elsewhere.
        if (e.key.startsWith("Arrow") || e.key === "Home" || e.key === "End") setHoveredId(null);
        // Typeahead is navigation too: a printable-key jump moves the cursor,
        // so the stationary pointer's row releases the hover the same way.
        if (typeahead && e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
          setHoveredId(null);
        }
        // Drilled into a submenu: ArrowLeft and Escape pop one level instead of
        // closing the menu, mirroring the flyout's own key model.
        if (activeSub !== null && (e.key === "ArrowLeft" || e.key === "Escape")) {
          e.preventDefault();
          e.stopPropagation();
          popSub();
          onKeyDown?.(e);
          return;
        }
        if ((e.key === "Enter" || e.key === " ") && highlighted !== null) {
          const handler = customActivators.current.get(highlighted);
          if (handler) {
            e.preventDefault();
            handler();
            return;
          }
        }
        if (e.key === "ArrowRight") {
          const container = menuRef.current;
          const activeId = container?.getAttribute("aria-activedescendant");
          if (activeId) {
            const activeEl = container?.ownerDocument.getElementById(activeId);
            if (activeEl?.getAttribute("aria-haspopup") === "menu") {
              e.preventDefault();
              activeEl.click();
              onKeyDown?.(e);
              return;
            }
          }
        }
        if (e.key === "Escape" && onClose) {
          // Consume the Escape so a menu inside a native <dialog> closes only the
          // menu instead of also firing the dialog's cancel event.
          e.preventDefault();
          onClose();
        }
        if (e.key === "Tab" && onClose) {
          // Consume the Tab as well: a menu is normally portaled, so "the next
          // tabbable after the menu" is a DOM accident, and letting native Tab
          // run against the closing tree races whatever restores focus to the
          // trigger. Closing lands focus on the trigger; Tab again moves on.
          e.preventDefault();
          onClose();
        }
        onKeyDown?.(e);
      },
      role: "menu",
      itemRole,
      typeahead,
      autoFocus,
      items,
      getItemId: getEncodedListboxItemId,
      ref: composedRef,
    });

  // Latest refs, not state sync: popSub is created before useListbox returns its
  // highlight setter and must keep a stable identity for the submenu effect that
  // calls it, so it reads both through refs instead of a stale closure.
  useEffect(() => {
    activeSubRef.current = activeSub;
    highlightRef.current = handleItemHighlight;
  }, [activeSub, handleItemHighlight]);

  const wrappedActivate = useCallback(
    (id: string) => {
      const handler = customActivators.current.get(id);
      if (handler) {
        handleItemHighlight(id as TId);
        handler();
        return;
      }
      handleItemActivate(id as TId);
    },
    [handleItemActivate, handleItemHighlight],
  );

  const notifySelect = useCallback(
    (id: string) => {
      onSelect?.(id as TId);
    },
    [onSelect],
  );

  // Public TId narrows the API; internal context stays string-keyed because the
  // DOM uses data-value strings and child MenuItem ids are opaque to TS.
  const contextValue: MenuContextValue = useMemo(
    () => ({
      selectedId,
      highlighted,
      hoveredId,
      hover,
      unhover,
      trackPointer,
      activate: wrappedActivate,
      notifySelect,
      highlight: handleItemHighlight as (id: string) => void,
      variant,
      idPrefix,
      itemRole,
      typeahead,
      registerItem: handleRegisterItem,
      unregisterItem,
      registerActivator,
      unregisterActivator,
      activeSub,
      pushSub,
      popSub,
      stackContainer,
    }),
    [
      selectedId,
      highlighted,
      hoveredId,
      hover,
      unhover,
      trackPointer,
      wrappedActivate,
      notifySelect,
      handleItemHighlight,
      variant,
      idPrefix,
      itemRole,
      typeahead,
      handleRegisterItem,
      unregisterItem,
      registerActivator,
      unregisterActivator,
      activeSub,
      pushSub,
      popSub,
      stackContainer,
    ],
  );

  return (
    <MenuContext value={contextValue}>
      {/* biome-ignore lint/a11y/useAriaPropsSupportedByRole: getContainerProps applies role="menu"/"listbox" dynamically, which Biome cannot resolve; aria-label is valid for those roles. */}
      <div
        {...rootProps}
        {...getContainerProps()}
        data-slot="menu"
        aria-label={ariaLabel}
        className={cn("w-full relative outline-none", className)}
      >
        {activeSub !== null ? <MenuStackBack label={activeSub.label} /> : null}
        {/* Drill-down region. A stacked submenu portals its items here, so they
            sit in the same role="menu" container at the same width — and the
            parent list below is `hidden`, which drops it from the accessibility
            tree AND from the selectable collection, so arrow navigation and
            typeahead never reach an item the user cannot see. */}
        <div
          ref={setStackContainer}
          role="none"
          data-slot="menu-stack"
          hidden={activeSub === null}
        />
        <div role="none" data-slot="menu-list" hidden={activeSub !== null}>
          {children}
        </div>
      </div>
    </MenuContext>
  );
}

"use client";

import {
  type ComponentPropsWithRef,
  type ReactNode,
  type Ref,
  useId,
  useLayoutEffect,
  useRef,
} from "react";
import { useComposedRefs } from "@/hooks/use-composed-refs";
import { getEncodedListboxItemId } from "@/hooks/use-listbox";
import { cn } from "@/lib/utils";
import { useMenuContext } from "./menu-context";
import { DefaultItemLayout, DetailItemLayout } from "./menu-item-layouts";
import { getItemState, menuItemBase, menuItemValue } from "./menu-item-variants";
import { useMenuItemInteractions } from "./use-menu-item-interactions";

/** Colour treatment for a detail value. */
type MenuItemValueVariant = "default" | "success" | "success-badge" | "muted";

/**
 * Glyph prepended to a detail value. Only the success variants get one, and it is the
 * non-color carrier of "passing" in a monochrome palette — informative, not decorative,
 * so it stays in the accessibility tree.
 */
const MENU_VALUE_GLYPHS: Partial<Record<MenuItemValueVariant, string>> = {
  success: "✓",
  "success-badge": "✓",
};

export interface MenuItemProps<TId extends string = string>
  extends Omit<
    ComponentPropsWithRef<"div">,
    "id" | "children" | "role" | "aria-checked" | "aria-disabled" | "data-value" | "ref"
  > {
  /** Stable identifier matched against selectedId/highlighted and passed to onSelect. */
  id: TId;
  /** Disables activation while keeping the item in the navigation order with aria-disabled. */
  disabled?: boolean;
  /** Danger applies destructive coloring for destructive actions. */
  variant?: "default" | "danger";
  /** Decorative hotkey label rendered as [n]. Does not bind a key listener. */
  hotkey?: number | string;
  /**
   * Leading icon rendered in the indicator slot. Replaces the default ▌ cursor and hover
   * chevron when provided.
   */
  icon?: ReactNode;
  /** Detail variant only. Right-aligned value (badge, count, or status text). */
  value?: ReactNode;
  /**
   * Color treatment for the detail value. The success variants prefix a ✓ so the passing
   * state does not rest on color alone.
   */
  valueVariant?: MenuItemValueVariant;
  /** Item label. */
  children: ReactNode;
  /** Ref forwarded to the underlying element. */
  ref?: Ref<HTMLDivElement>;
}

/** Selectable item with optional hotkey, value, variant. */
export function MenuItem<TId extends string = string>({
  id,
  disabled = false,
  variant = "default",
  hotkey,
  icon,
  value,
  valueVariant = "default",
  children,
  className,
  ref,
  onClick,
  onFocus,
  onMouseDown,
  onPointerMove,
  onPointerLeave,
  ...rootProps
}: MenuItemProps<TId>) {
  const {
    selectedId,
    highlighted,
    hoveredId,
    activate,
    highlight,
    hover,
    unhover,
    trackPointer,
    variant: menuVariant,
    idPrefix,
    itemRole,
    registerItem,
    unregisterItem,
  } = useMenuContext();
  const registrationId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const composedRef = useComposedRefs(rootRef, ref);

  useLayoutEffect(() => {
    registerItem(registrationId, id, disabled, rootRef.current);
    return () => unregisterItem(registrationId);
  }, [registerItem, unregisterItem, registrationId, id, disabled]);

  const isSelected = !disabled && selectedId === id;
  const isFocused = highlighted === id;
  const isActive = !disabled && (isFocused || isSelected);
  const isDanger = variant === "danger";
  const isDetail = menuVariant === "detail";
  const state = getItemState({ disabled, isFocused, isSelected, isHovered: hoveredId === id });
  // Post-precedence: a row that is both hovered and keyboard-highlighted renders
  // the keyboard treatment, so hover visuals exist only in the "hovered" state.
  const isHovered = state === "hovered";
  const itemId = getEncodedListboxItemId(idPrefix, id);

  const { handleClick, handleFocus, handleMouseDown, handlePointerMove, handlePointerLeave } =
    useMenuItemInteractions({
      id,
      disabled,
      activate,
      highlight,
      hover,
      unhover,
      trackPointer,
      onClick,
      onFocus,
      onMouseDown,
      onPointerMove,
      onPointerLeave,
    });

  return (
    // biome-ignore lint/a11y/noStaticElementInteractions: menuitem with centralized keyboard handling — the menu container owns arrow/Enter/Space via useNavigation; the item only mirrors focus/click.
    // biome-ignore lint/a11y/useAriaPropsSupportedByRole: role is the dynamic itemRole (menuitem/menuitemradio) that Biome cannot resolve; aria-checked is valid for menuitemradio.
    // biome-ignore lint/a11y/useKeyWithClickEvents: Enter/Space activation is handled centrally by the menu container, not per item.
    <div
      {...rootProps}
      ref={composedRef}
      id={itemId}
      role={itemRole}
      tabIndex={-1}
      data-slot="menu-item"
      data-diffgazer-navigation-item="true"
      data-value={id}
      data-highlighted={isFocused ? "" : undefined}
      data-hovered={isHovered ? "" : undefined}
      aria-checked={itemRole === "menuitemradio" ? isSelected : undefined}
      aria-disabled={disabled || undefined}
      data-selected={isSelected ? "" : undefined}
      onMouseDown={handleMouseDown}
      onClick={handleClick}
      onFocus={handleFocus}
      onPointerMove={handlePointerMove}
      onPointerLeave={handlePointerLeave}
      className={cn(menuItemBase({ menuVariant, state, colorVariant: variant }), className)}
    >
      {isDetail ? (
        <DetailItemLayout
          isFocused={isFocused}
          isSelected={isSelected}
          isHovered={isHovered}
          value={value}
          valueClassName={menuItemValue({ valueVariant, active: isActive })}
          valueGlyph={MENU_VALUE_GLYPHS[valueVariant]}
          icon={icon}
        >
          {children}
        </DetailItemLayout>
      ) : (
        <DefaultItemLayout
          isFocused={isFocused}
          isSelected={isSelected}
          isHovered={isHovered}
          isDanger={isDanger}
          hotkey={hotkey}
          icon={icon}
        >
          {children}
        </DefaultItemLayout>
      )}
    </div>
  );
}

import { cva } from "class-variance-authority";

export type ItemState =
  | "normal"
  | "focused"
  | "selected"
  | "hovered"
  | "disabled"
  | "disabledFocused";

export function getItemState(options: {
  disabled: boolean;
  isFocused: boolean;
  isSelected: boolean;
  isHovered: boolean;
}): ItemState {
  const { disabled, isFocused, isSelected, isHovered } = options;
  if (disabled && isFocused) return "disabledFocused";
  if (disabled) return "disabled";
  if (isFocused) return "focused";
  if (isSelected) return "selected";
  if (isHovered) return "hovered";
  return "normal";
}

export const menuItemBase = cva("cursor-pointer w-full transition-colors", {
  variants: {
    menuVariant: {
      default: "px-4 py-3 flex items-center font-mono duration-75",
      // No per-row rule: a hairline under every row reads as a data table.
      // The right-aligned dim value column carries the rhythm instead, and
      // MenuDivider still draws real group boundaries.
      detail: "px-4 py-4 flex justify-between items-center text-sm",
    },
    // No CSS :hover anywhere in here: hover is JS state (data-hovered, set by
    // real pointer travel in useMenuItemInteractions and cleared by navigation
    // keys), so a stationary cursor can never keep a stale affordance on a row
    // the keyboard has left. The keyboard cursor (focused) always outranks it.
    state: {
      normal: "",
      focused: "font-bold",
      selected: "font-bold",
      hovered: "bg-secondary text-foreground",
      disabled: "opacity-50 cursor-not-allowed",
      disabledFocused: "opacity-60 cursor-not-allowed bg-secondary text-foreground",
    },
    colorVariant: {
      default: "",
      danger: "",
    },
  },
  compoundVariants: [
    {
      colorVariant: "danger",
      state: "focused",
      class: "bg-error text-error-foreground",
    },
    { colorVariant: "default", state: "focused", class: "bg-primary text-primary-foreground" },
    {
      colorVariant: "danger",
      state: "selected",
      class: "bg-error text-error-foreground",
    },
    { colorVariant: "default", state: "selected", class: "bg-primary text-primary-foreground" },
    { colorVariant: "danger", state: "normal", menuVariant: "default", class: "text-error" },
    // Hover is subordinate: danger rows keep their palette under it.
    { colorVariant: "danger", state: "hovered", menuVariant: "default", class: "text-error" },
  ],
  defaultVariants: { menuVariant: "default", state: "normal", colorVariant: "default" },
});

export const menuItemIndicator = cva(
  "pr-4 shrink-0 inline-flex items-center justify-center self-center leading-none font-mono text-xs",
  {
    variants: {
      idle: {
        true: "opacity-60",
        false: "",
      },
    },
    defaultVariants: { idle: false },
  },
);

export const menuItemValue = cva("font-mono text-xs", {
  variants: {
    valueVariant: {
      default: "",
      success: "",
      "success-badge": "border px-2 py-0.5 rounded",
      muted: "",
    },
    active: {
      true: "uppercase tracking-wide",
      false: "",
    },
  },
  compoundVariants: [
    { valueVariant: "default", active: false, class: "text-muted-foreground" },
    { valueVariant: "success", active: false, class: "text-success" },
    {
      valueVariant: "success-badge",
      active: false,
      class: "text-success border-success/30 bg-success/10",
    },
    { valueVariant: "muted", active: false, class: "text-muted-foreground/60" },
    { valueVariant: "default", active: true, class: "text-current" },
    { valueVariant: "success", active: true, class: "text-current" },
    { valueVariant: "muted", active: true, class: "text-current" },
    {
      valueVariant: "success-badge",
      active: true,
      class: "border-success bg-success text-success-foreground",
    },
  ],
  defaultVariants: { valueVariant: "default", active: false },
});

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";
import { Chevron } from "../icons/chevron";

/** Keyboard-cursor glyph. Exclusively the keyboard's: hover never paints it. */
const INDICATOR_ACTIVE = "▌";

const iconSlotBase =
  "pr-4 shrink-0 inline-flex w-5 items-center justify-center self-center leading-none relative -top-[2px]";

/**
 * Fixed-width slot: "▌" for the keyboard cursor, a chevron on the hovered row,
 * empty when idle. The slot always renders at w-5, so revealing the chevron
 * never shifts the label column.
 */
function MenuItemIndicator({
  isFocused,
  isSelected,
  isHovered,
  className,
}: {
  isFocused: boolean;
  isSelected: boolean;
  isHovered: boolean;
  className?: string;
}) {
  const showCursor = isFocused || isSelected;
  return (
    <span aria-hidden="true" className={cn(iconSlotBase, className)}>
      {showCursor && INDICATOR_ACTIVE}
      {/* top-[2px] cancels the slot's text-baseline offset, which an SVG doesn't share. */}
      {!showCursor && isHovered && (
        <Chevron direction="right" size="sm" className="relative top-[2px]" />
      )}
    </span>
  );
}

