/** Trigger item that opens the submenu. */
export function MenuSubTrigger({
  id,
  disabled = false,
  children,
  className,
  ref,
}: MenuSubTriggerProps) {
  const {
    highlighted,
    hoveredId,
    highlight,
    hover,
    unhover,
    trackPointer,
    idPrefix,
    registerItem,
    unregisterItem,
    registerActivator,
    unregisterActivator,
  } = useMenuContext();
  const { open, onOpenChange, triggerRef, setTriggerItemId, triggerInfoRef, resolvedMode } =
    useMenuSubContext();
  const registrationId = useId();
  const composedRef = useComposedRefs(triggerRef, ref);

  const isFocused = highlighted === id;
  const itemId = getEncodedListboxItemId(idPrefix, id);
  const state = getItemState({
    disabled,
    isFocused,
    isSelected: false,
    isHovered: hoveredId === id,
  });
  const isHovered = state === "hovered";

  useLayoutEffect(() => {
    registerItem(registrationId, id, disabled, triggerRef.current);
    return () => unregisterItem(registrationId);
  }, [registerItem, unregisterItem, registrationId, id, disabled, triggerRef]);

  // Publish the trigger's DOM id so MenuSubContent can label itself by its
  // trigger (aria-labelledby) instead of a generic name.
  useLayoutEffect(() => {
    setTriggerItemId(itemId);
    return () => setTriggerItemId(null);
  }, [setTriggerItemId, itemId]);

  // Published through a ref, not state: the label is arbitrary JSX whose
  // identity changes every render, so storing it in state would loop.
  useLayoutEffect(() => {
    triggerInfoRef.current = { id, label: children };
  }, [triggerInfoRef, id, children]);

  useEffect(() => {
    const openSubmenu = () => {
      if (!disabled) onOpenChange(true);
    };
    registerActivator(id, openSubmenu);
    return () => unregisterActivator(id);
  }, [id, disabled, onOpenChange, registerActivator, unregisterActivator]);

  // Close an open submenu when the parent menu's highlight moves off this
  // trigger — this also enforces one open submenu per level, since opening a
  // sibling highlights that sibling and unhighlights this one. In stack mode the
  // highlight deliberately moves INTO the submenu, so the parent stack enforces
  // the one-open rule instead.
  useEffect(() => {
    if (resolvedMode === "stack") return;
    if (open && highlighted !== null && highlighted !== id) onOpenChange(false);
  }, [resolvedMode, open, highlighted, id, onOpenChange]);

  const { handleClick, handleFocus, handleMouseDown, handlePointerMove, handlePointerLeave } =
    useMenuItemInteractions({
      id,
      disabled,
      // Activation for a trigger is toggling its submenu, not selecting a value.
      activate: () => onOpenChange(!open),
      highlight,
      hover,
      unhover,
      trackPointer,
    });

  return (
    // biome-ignore lint/a11y/useKeyWithClickEvents: arrow/Enter open-submenu handling is centralized on the menu container, not on this item.
    <div
      {...(disabled ? {} : OVERLAY_TRIGGER_PROPS)}
      ref={composedRef}
      id={itemId}
      // APG: a submenu trigger is always a menuitem, never menuitemradio. Pinning
      // the role keeps it from inheriting the menu-wide selection itemRole, which
      // would render menuitemradio without the required aria-checked.
      role="menuitem"
      tabIndex={-1}
      data-slot="menu-sub-trigger"
      data-diffgazer-navigation-item="true"
      data-value={id}
      data-highlighted={isFocused ? "" : undefined}
      data-hovered={isHovered ? "" : undefined}
      aria-haspopup="menu"
      aria-expanded={open}
      aria-disabled={disabled || undefined}
      onMouseDown={handleMouseDown}
      onClick={handleClick}
      onFocus={handleFocus}
      onPointerMove={handlePointerMove}
      onPointerLeave={handlePointerLeave}
      className={cn(menuItemBase({ menuVariant: "default", state }), className)}
    >
      {/* isHovered={false}: like the back row, a trigger's own glyph (the
          trailing chevron) already carries the affordance, so hover gives it
          the subordinate background only — never a second chevron. */}
      <DefaultItemLayout
        isFocused={isFocused}
        isSelected={false}
        isHovered={false}
        isDanger={false}
      >
        {children}
      </DefaultItemLayout>
      <Chevron size="sm" className="ml-auto" />
    </div>
  );
}

export interface MenuSubContentProps {
  /** Menu items rendered inside the submenu floating panel. */
  children: ReactNode;
  /** Additional class names merged onto the rendered element. */
  className?: string;
  /** Offset from the trigger edge in pixels. */
  sideOffset?: number;
  /** Accessible name for the menu container (role="menu"). */
  "aria-label"?: string;
  /** ID of the element that labels this component. */
  "aria-labelledby"?: string;
}

/** Floating panel for submenu content. */
export function MenuSubContent({
  children,
  className,
  sideOffset = 0,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
}: MenuSubContentProps) {
  const { open, onOpenChange, triggerRef, triggerItemId, resolvedMode, triggerInfoRef } =
    useMenuSubContext();
  const parentMenu = useMenuContext();
  const contentRef = useRef<HTMLDivElement>(null);
  const isStack = resolvedMode === "stack";
  const { pushSub, popSub, activeSub, stackContainer } = parentMenu;
  const triggerId = triggerInfoRef.current?.id ?? null;
  const isPushed = isStack && triggerId !== null && activeSub?.id === triggerId;
  const firstStackItemId =
    collectListboxItems(children, {
      itemTypes: [MenuItem, MenuItemCheckbox, MenuItemRadio],
      containerTypes: [MenuGroup],
    }).find((item) => !item.disabled)?.id ?? null;

  // The trigger row is hidden once we push, so the highlight has to follow the
  // user into the submenu rather than point at an element that no longer
  // exists. Effect Event, not a dependency: a first row that changes identity
  // (async children, the current first row becoming disabled) must not pop and
  // re-push the stack entry and yank the highlight back to the top.
  const highlightStackEntry = useEffectEvent(() => {
    if (firstStackItemId !== null) parentMenu.highlight(firstStackItemId);
  });

  // The drill-down stack lives on the parent Menu, so publishing this submenu
  // into it is synchronisation with an external store, not derived state. The
  // cleanup pops only our own entry, so a sibling push is never clobbered.
  useEffect(() => {
    if (!isStack || !open) return;
    const info = triggerInfoRef.current;
    if (info === null) return;
    pushSub(info);
    highlightStackEntry();
    return () => popSub(info.id);
  }, [isStack, open, pushSub, popSub, triggerInfoRef]);

  // The parent pops for the back row, ArrowLeft, Escape and sibling pushes, so
  // losing the entry has to release this submenu's own open state too.
  useEffect(() => {
    if (!isPushed) return;
    return () => onOpenChange(false);
  }, [isPushed, onOpenChange]);

  const returnFocusToParent = () => {
    onOpenChange(false);
    const container = triggerRef.current?.closest('[role="menu"]') as HTMLElement | null;
    if (container) {
      container.focus({ preventScroll: true });
    }
    if (triggerId !== null) parentMenu.highlight(triggerId);
  };

  const dismissSubmenu = () => {
    onOpenChange(false);
  };

  // Default overlay dismissal: an outside pointerdown (not on the trigger or the
  // submenu itself) closes the submenu, matching Select's FloatingPanel wiring.
  useOutsideClick(contentRef, dismissSubmenu, open, [triggerRef]);

  const handleSubmenuKeyDown = (event: KeyboardEvent) => {
    if (event.key === "ArrowRight") {
      event.stopPropagation();
      return;
    }
    if (event.key === "Tab") {
      event.preventDefault();
      event.stopPropagation();
      returnFocusToParent();
      return;
    }
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      event.stopPropagation();
      returnFocusToParent();
      return;
    }
    if (event.key === "Escape") {
      // preventDefault so a submenu open inside a native <dialog> consumes the
      // Escape instead of also firing the dialog's cancel event.
      event.preventDefault();
      event.stopPropagation();
      returnFocusToParent();
      return;
    }
  };

  // Label the submenu by its trigger; consumer aria-label/aria-labelledby wins.
  const resolvedAriaLabelledBy =
    ariaLabelledBy ?? (ariaLabel ? undefined : (triggerItemId ?? undefined));

  if (isStack) {
    // Drill-down: the items portal into the parent panel's stack region, so they
    // inherit its surface, width and left edge verbatim and stay inside the one
    // role="menu" container — no second menu, no nested roles, no new chrome.
    if (!isPushed || stackContainer === null) return null;
    return createPortal(children, stackContainer);
  }

  return (
    <FloatingPanel
      open={open}
      triggerRef={triggerRef as RefObject<HTMLElement | null>}
      side="right"
      align="start"
      sideOffset={sideOffset}
      role="presentation"
      className={cn("min-w-[8rem]", OVERLAY_SURFACE, className)}
    >
      <MenuRoot
        ref={contentRef}
        aria-label={ariaLabel}
        aria-labelledby={resolvedAriaLabelledBy}
        autoFocus={open}
        typeahead={parentMenu.typeahead}
        // No onClose: handleSubmenuKeyDown owns Escape/Tab dismissal and also
        // restores focus and the parent highlight. Wiring both would call the
        // public onOpenChange twice for one keystroke.
        onSelect={parentMenu.notifySelect}
        onKeyDown={handleSubmenuKeyDown}
      >
        {children}
      </MenuRoot>
    </FloatingPanel>
  );
}

"use client";

import { type ReactNode, useCallback, useEffect, useId, useLayoutEffect, useRef } from "react";
import { getEncodedListboxItemId } from "@/hooks/use-listbox";
import { cn } from "@/lib/utils";
import { useMenuContext } from "./menu-context";
import { getItemState, menuItemBase } from "./menu-item-variants";
import { useMenuItemInteractions } from "./use-menu-item-interactions";

/** Reserved item id for the drill-down back row. */
export const MENU_STACK_BACK_ID = "__menu-stack-back";

interface MenuStackBackProps {
  /** Parent trigger label echoed in the row. */
  label: ReactNode;
}

/**
 * Sticky first row of a drilled-down submenu: the breadcrumb and the pop
 * control in one. It is a real button registered like any other menu item, so
 * roving focus, `aria-activedescendant`, and ArrowDown-wrapping reach it with no
 * special-casing, and it is a compliant touch target.
 */
export function MenuStackBack({ label }: MenuStackBackProps) {
  const {
    highlighted,
    hoveredId,
    highlight,
    hover,
    unhover,
    trackPointer,
    idPrefix,
    registerItem,
    unregisterItem,
    registerActivator,
    unregisterActivator,
    popSub,
  } = useMenuContext();
  const registrationId = useId();
  const rowRef = useRef<HTMLButtonElement>(null);
  // Wrapped: popSub takes an optional entry id, and a bare handler reference
  // would hand it the click event instead.
  const pop = useCallback(() => popSub(), [popSub]);

  const isFocused = highlighted === MENU_STACK_BACK_ID;
  const state = getItemState({
    disabled: false,
    isFocused,
    isSelected: false,
    isHovered: hoveredId === MENU_STACK_BACK_ID,
  });
  const isHovered = state === "hovered";

  const { handleClick, handleFocus, handleMouseDown, handlePointerMove, handlePointerLeave } =
    useMenuItemInteractions<HTMLButtonElement>({
      id: MENU_STACK_BACK_ID,
      disabled: false,
      activate: pop,
      highlight,
      hover,
      unhover,
      trackPointer,
    });

  useLayoutEffect(() => {
    registerItem(registrationId, MENU_STACK_BACK_ID, false, rowRef.current);
    return () => unregisterItem(registrationId);
  }, [registerItem, unregisterItem, registrationId]);

  useEffect(() => {
    registerActivator(MENU_STACK_BACK_ID, pop);
    return () => unregisterActivator(MENU_STACK_BACK_ID);
  }, [registerActivator, unregisterActivator, pop]);

  return (
    <button
      ref={rowRef}
      type="button"
      id={getEncodedListboxItemId(idPrefix, MENU_STACK_BACK_ID)}
      // APG: the back row is a command inside the same menu, never a radio, so
      // the role is pinned rather than inherited from the menu-wide itemRole.
      role="menuitem"
      tabIndex={-1}
      data-slot="menu-stack-back"
      data-diffgazer-navigation-item="true"
      data-value={MENU_STACK_BACK_ID}
      data-highlighted={isFocused ? "" : undefined}
      data-hovered={isHovered ? "" : undefined}
      onMouseDown={handleMouseDown}
      onClick={handleClick}
      onFocus={handleFocus}
      onPointerMove={handlePointerMove}
      onPointerLeave={handlePointerLeave}
      className={cn(
        menuItemBase({ menuVariant: "default", state }),
        "min-h-11 gap-2 border-b border-border text-left",
        isFocused ? "" : "text-muted-foreground",
      )}
    >
      <span aria-hidden="true">‹</span>
      {/* The label is arbitrary JSX, so the accessible name is composed from a
          visually-hidden prefix rather than a stringified aria-label. */}
      <span className="sr-only">Back to</span> <span>{label}</span>
    </button>
  );
}
